import Config

# Note we also include the path to a cache manifest
# containing the digested version of static files. This
# manifest is generated by the `mix assets.deploy` task,
# which you should run after static files are built and
# before starting your production server.
config :patchbay, PatchbayWeb.Endpoint, cache_static_manifest: "priv/static/cache_manifest.json"

# Every request reaches production through Fly's proxy, which sets Fly-Client-IP.
config :patchbay, :behind_fly_proxy, true
config :patchbay, :secure_session_cookie, true

# The port `fly.toml` names under `[metrics]`. Fly sends no public traffic to it.
config :patchbay, :metrics_listener, ip: {0, 0, 0, 0, 0, 0, 0, 0}, port: 9091

# Force using SSL in production. This also sets the "strict-transport-security" header,
# known as HSTS. Note `:force_ssl` is required to be set at compile-time.
#
# The platform health check reaches the machine directly rather than through the
# public proxy, so its plain HTTP request must not be redirected.
config :patchbay, PatchbayWeb.Endpoint,
  force_ssl: [
    rewrite_on: [:x_forwarded_proto],
    exclude: [hosts: ["localhost", "127.0.0.1"], paths: ["/healthz"]]
  ]

# Configure Swoosh API Client
config :swoosh, api_client: Swoosh.ApiClient.Req

# Disable Swoosh Local Memory Storage
config :swoosh, local: false

# Do not print debug messages in production
config :logger, level: :info

# The visit lines (PatchbayWeb.VisitLog) say what each request and page did,
# by route. Phoenix's own request and connection lines would repeat them with
# each raw path and its parameters, so they are off.
config :phoenix, :logger, false

# Runtime production configuration, including reading
# of environment variables, is done on config/runtime.exs.
